  "a1.award.1": "🏅 <strong>Prix Roi de la Quantité</strong> — Le plus de minutes gratuites par mois (~40 min)",
  "a1.h2.2": "<span class=\"num\">02</span> <a href=\"https://klingai.com\" target=\"_blank\" rel=\"noopener\">Kling AI 3.0</a> — La Puissance Cinématographique",
