Object.assign(window.__yd_extra_en || (window.__yd_extra_en = {}), {
  "nav.article6": "Best Times for Newsletters & Videos",
  "a6.meta": "June 5, 2026 · 5 min read",
  "a6.date": "June 2026",
  "a6.card.title": "Best Times to Send a Newsletter or Post a Video (2026 Data)",
  "a6.card.excerpt": "Day, time, platform: the 2026 data on the best slots for newsletters, YouTube, Shorts/TikTok, and LinkedIn — summarised in one quick-reference table.",
  "a6.title": "Best Times to Send<br/><em>Newsletters &amp; Post Videos</em>",
  "a6.lede": "Publishing at the right time can double your open rate or triple your views — without changing a word of content. Here's what the 2026 data says, platform by platform.",
  "a6.callout.intro": "These are global averages. The best time for your audience is the one you discover by testing — but these windows are the best starting point.",
  "a6.h2.1": "<span class=\"num\">01</span> Newsletters — When to Hit Send",
  "a6.p1": "Newsletter timing directly impacts open rates. People check email at very specific times — and most emails not opened in the first 4 hours will never be opened at all.",
  "a6.table1.head": "<th>Slot</th><th>Day</th><th>Time</th><th>Why It Works</th>",
  "a6.table1.body": "<tr><td><span class=\"badge badge--green\">🥇 Optimal</span></td><td><strong>Tuesday</strong></td><td>10am – 11am</td><td>Week is in motion, not yet overwhelmed. Highest open rates of the week.</td></tr><tr><td><span class=\"badge badge--green\">🥈 Very Good</span></td><td><strong>Thursday</strong></td><td>10am – 11am</td><td>Second best day. Readers are still in their weekly rhythm.</td></tr><tr><td><span class=\"badge badge--blue\">🥉 Decent</span></td><td><strong>Wednesday</strong></td><td>2pm – 3pm</td><td>Mid-week — good for longer content and digests.</td></tr><tr><td><span class=\"badge badge--gold\">📱 Mobile</span></td><td><strong>Sunday</strong></td><td>8pm – 9pm</td><td>Mobile readers often check email Sunday evening before the week starts. Ideal for lifestyle or weekly newsletters.</td></tr><tr><td><span class=\"badge badge--red\">⚠️ Avoid</span></td><td><strong>Monday</strong></td><td>All day</td><td>Inbox overloaded. Your email drowns in the weekend backlog.</td></tr><tr><td><span class=\"badge badge--red\">⚠️ Avoid</span></td><td><strong>Friday pm</strong></td><td>After 3pm</td><td>People are already in weekend mode. Open rates drop sharply.</td></tr>",
  "a6.tips.newsletter": "<li><span class=\"feature-icon\">✓</span> Send between 9:30am and 11am to catch the morning desk audience</li><li><span class=\"feature-icon\">✓</span> Test Tuesday vs Thursday over 4 sends each before picking your fixed day</li><li><span class=\"feature-icon\">✓</span> Keep a consistent time — your subscribers get used to it and anticipate it</li><li><span class=\"feature-icon warn\">!</span> Avoid sending the same day as a major news event in your sector</li>",
  "a6.h2.2": "<span class=\"num\">02</span> YouTube — Maximise Launch Views",
  "a6.p2": "The first 24–48 hours of a YouTube video are decisive. The algorithm judges initial engagement velocity to decide whether to push the video into recommendations.",
  "a6.table2.head": "<th>Slot</th><th>Day</th><th>Time</th><th>Why</th>",
  "a6.table2.body": "<tr><td><span class=\"badge badge--green\">🥇 Optimal</span></td><td><strong>Friday</strong></td><td>3pm – 5pm</td><td>People start winding down. Peak video consumption through the evening and weekend.</td></tr><tr><td><span class=\"badge badge--green\">🥈 Very Good</span></td><td><strong>Saturday</strong></td><td>10am – 12pm</td><td>Weekend morning — high attention availability, no obligations yet.</td></tr><tr><td><span class=\"badge badge--blue\">🥉 Decent</span></td><td><strong>Wednesday</strong></td><td>12pm – 2pm</td><td>Lunch break — good for short formats and tutorials.</td></tr><tr><td><span class=\"badge badge--red\">⚠️ Avoid</span></td><td><strong>Mon – Tue</strong></td><td>Morning</td><td>Attention captured by work. Low watch-through rates.</td></tr>",
  "a6.tip.youtube": "Publish 1–2 hours before your usual traffic peak — YouTube needs this time to index and begin distributing the video. If your audience is mainly in France, align to French time zones.",
  "a6.h2.3": "<span class=\"num\">03</span> YouTube Shorts &amp; TikTok — Short-Form Content",
  "a6.p3": "Shorts and TikToks follow a different logic: the algorithm can launch a video at any time. But the timing of the first peak influences initial distribution.",
  "a6.table3.head": "<th>Platform</th><th>Best Days</th><th>Best Times</th><th>Note</th>",
  "a6.table3.body": "<tr><td><strong>YouTube Shorts</strong></td><td>Fri, Sat, Sun</td><td>6pm – 10pm</td><td>Weekend evenings — high passive mobile consumption</td></tr><tr><td><strong>TikTok</strong></td><td>Tue, Thu, Fri</td><td>7pm – 9pm</td><td>Peak TikTok session in the evening, before sleep</td></tr><tr><td><strong>TikTok (US)</strong></td><td>Tue, Thu</td><td>2pm – 4pm (EST)</td><td>If your target audience is North American</td></tr>",
  "a6.h2.4": "<span class=\"num\">04</span> LinkedIn — For Founders and B2B",
  "a6.p4": "LinkedIn is a desktop platform. Its activity peaks follow professional rhythms, not leisure ones.",
  "a6.table4.head": "<th>Slot</th><th>Day</th><th>Time</th><th>Context</th>",
  "a6.table4.body": "<tr><td><span class=\"badge badge--green\">🥇 Optimal</span></td><td><strong>Tue – Wed</strong></td><td>8am – 10am</td><td>Professionals check LinkedIn arriving at the office or starting remote work</td></tr><tr><td><span class=\"badge badge--green\">🥈 Very Good</span></td><td><strong>Thursday</strong></td><td>12pm – 1pm</td><td>Lunch break — LinkedIn scroll before or after eating</td></tr><tr><td><span class=\"badge badge--red\">⚠️ Avoid</span></td><td><strong>Weekend</strong></td><td>—</td><td>Engagement drops 70% on Saturday and Sunday</td></tr>",
  "a6.h2.summary": "📊 Quick-Reference Summary",
  "a6.table5.head": "<th>Channel</th><th>Best Day</th><th>Best Time</th><th>Avoid</th>",
  "a6.table5.body": "<tr><td>📧 <strong>Newsletter</strong></td><td>Tuesday or Thursday</td><td>10am – 11am</td><td>Monday, Friday pm</td></tr><tr><td>▶️ <strong>YouTube</strong></td><td>Friday</td><td>3pm – 5pm</td><td>Mon – Tue morning</td></tr><tr><td>📱 <strong>Shorts / TikTok</strong></td><td>Friday – Sunday</td><td>6pm – 10pm</td><td>Tue – Wed morning</td></tr><tr><td>💼 <strong>LinkedIn</strong></td><td>Tuesday – Wednesday</td><td>8am – 10am</td><td>Weekend</td></tr>",
  "a6.callout.final": "Consistency beats perfect timing. Content published every week at the same 'decent' time always outperforms content published irregularly at the 'optimal' moment. Pick a slot you can hold, and hold it.",
});

